  ...baseConfig,
  plugins: [
    ...baseConfig.plugins,
    [
      require.resolve('babel-plugin-module-resolver'),
      {
        root: ['.'],
        alias: {
          '~': '.',
          app: './overrides/app',
        },
      },
    ],
  ],
};

